enum nslSourceTypeEnum
{
  NSL_SOURCETYPE_SFX,
  NSL_SOURCETYPE_AMBIENT,
  NSL_SOURCETYPE_MUSIC,
  NSL_SOURCETYPE_VOICE,
  NSL_SOURCETYPE_MOVIE,
  NSL_SOURCETYPE_USER1,
  NSL_SOURCETYPE_USER2
};

struct nslSystem
{
  char padding0[0x15850];
  int initialized;
  char padding1[0x38];
  float sfxVolume;
  float ambientVolume;
  float musicVolume;
  float voiceVolume;
  float movieVolume;
  float user1Volume;
  float user2Volume;
};

extern nslSystem nsl;
extern const char nsl_not_initialized[];
void nslFatal(const char *format, ...);
__asm__(".equ nsl, 0x0049B5F0");
__asm__(".equ nsl_not_initialized, 0x0051C480");
__asm__(".equ nslFatal__FPCce, 0x00391420");

inline __attribute__((always_inline)) void _nslInitialized()
{
  if (!(nsl.initialized == 1))
    nslFatal(nsl_not_initialized);
}

float nslGetVolume( nslSourceTypeEnum typeOfSound )
{
  if (!nsl.initialized) return 1;
  _nslInitialized();
  switch(typeOfSound) 
  {
    case NSL_SOURCETYPE_SFX:      return nsl.sfxVolume;     break;
    case NSL_SOURCETYPE_MUSIC:    return nsl.musicVolume;   break;
    case NSL_SOURCETYPE_AMBIENT:  return nsl.ambientVolume; break;
    case NSL_SOURCETYPE_VOICE:    return nsl.voiceVolume;   break;
    case NSL_SOURCETYPE_MOVIE:    return nsl.movieVolume;   break;
    case NSL_SOURCETYPE_USER1:    return nsl.user1Volume;   break;
    case NSL_SOURCETYPE_USER2:    return nsl.user2Volume;   break;
    default: nslFatal(false && "Unhandled sourcetype"); break;
  };

  return 0.0f;
}
